// Writes the current date into a generated file, imported by SettingsDrawer
// to show "last updated" -- captured at BUILD time (this script runs via
// the `prebuild` npm hook, before `next build`), not at runtime in the
// browser. If this ran in browser code instead, it would show whatever
// date the visitor happened to load the page, not when the app was
// actually last deployed -- the whole point is knowing when a real
// deploy happened, not the current moment.
const fs = require('fs');
const path = require('path');

const date = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

const content = `// Auto-generated by scripts/generate-build-date.js at build time. Do not edit by hand.
export const BUILD_DATE = ${JSON.stringify(date)};
`;

fs.writeFileSync(path.join(__dirname, '..', 'lib', 'buildDate.generated.ts'), content);
console.log(`Generated build date: ${date}`);
